utton,input,select,textarea{font:inherit}button,a,input,select,textarea{min-height:44px}button{cursor:pointer;border:1px solid #ccd2da;border-radius:10px;padding:10px 16px;background:white;color:inherit}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #9c2d0f;outline-offset:3px}.primary{background:#18202d;color:white;border-color:#18202d}a{color:inherit;text-decoration:none;display:inline-flex;align-items:center;padding:8px}h1,h2,h3,p{margin:0 0 12px}h1{font-size:clamp(24px,4vw,36px);line-height:1.2;letter-spacing:-1px}small,.muted{color:#536073}small{font-size:13px}header,.row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.panel{background:#fff;border:1px solid #d6dce3;border-radius:18px;padding:24px}.pill{display:inline-flex;padding:5px 10px;border-radius:20px;background:#e9eee9;color:#35533c;font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}label{display:block;font-size:14px;font-weight:600;margin-bottom:6px}input,select,textarea{width:100%;border:1px solid #bcc6d1;padding:10px 12px;border-radius:9px;background:#fff;color:#18202d;margin-bottom:16px}input:focus{border-color:#9c2d0f}form{max-width:460px}output{display:block;color:#35533c;margin-top:12px}.art{border-radius:14px;background:linear-gradient(135deg,#c9dce2,#dae3dc);padding:30px;position:relative;overflow:hidden}.art:before{content:\"\";display:block;width:110px;height:110px;border:20px solid #fff8;border-radius:50%;margin:0 auto;animation:rotate 12s linear infinite}.art:after{content:\"\";position:absolute;inset:20% 35%;border:12px solid #18202d22;border-radius:12px;transform:rotate(35deg)}@keyframes rotate{to{transform:rotate(360deg)}}@media(max-width:600px){body{padding:16px}.grid{grid-template-columns:1fr}.panel{padding:18px}}@media(prefers-reduced-motion:reduce){*,*:before{animation:none!important;transition:none!important}}</style></head><body><article class=\"panel\" style=\"max-width:480px;margin:auto\"><div class=\"art\" style=\"height:190px\"></div><div class=\"row\" style=\"margin:20px 0 12px\"><span class=\"pill\">Product design</span><button id=\"save\" aria-pressed=\"false\">Save project</button></div><h1>Spaces for better work.</h1><p class=\"muted\">A calm digital workspace for a small, ambitious team.</p><details><summary style=\"cursor:pointer;min-height:44px;padding:10px 0\">Explore the project</summary><p>Responsive layouts, a shared task board and a simple weekly planning flow.</p><small>Built with HTML, CSS and JavaScript. Original demo content.</small></details><output id=\"saved\" aria-live=\"polite\"></output></article><script>document.querySelector('#save').addEventListener('click',e=>{const b=e.currentTarget,saved=b.getAttribute('aria-pressed')==='true';b.setAttribute('aria-pressed',String(!saved));b.textContent=saved?'Save project':'Saved \u2713';document.querySelector('#saved').textContent=saved?'Removed from sample saved projects.':'Added to sample saved projects.'})</script></body></html>","README.md":"# Portfolio project card\n\nVersion: 1.0.0\nOriginal getLancer curated recipe. Licence: MIT.\n\n## Setup\nOpen index.html in a modern browser. No packages, installation, API keys or external assets are required. Optional local server: python3 -m http.server 8000.\n\n## Try\nSave or unsave the project and expand its details.\n\n## Files\nindex.html contains the working HTML, CSS and JavaScript. LICENSE contains redistribution terms. README.md contains this setup guide.\n\n## Accessibility\nKeyboard controls, visible focus, 44px targets and reduced-motion support. Test your own modifications before release.\n\n## Dependencies\nNone. HTML/CSS and browser JavaScript only. No external fonts or images.\n\n## Data and limits\nSynthetic data held in preview memory. No account service, production credentials, tracking or network requests.\n","LICENSE":"MIT License\n\nCopyright (c) 2026 getLancer con