h=device-width,initial-scale=1\"><meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; connect-src 'none'; base-uri 'none'; form-action 'none'\"><title>Project pulse dashboard</title><style>*{box-sizing:border-box}body{margin:0;padding:24px;background:#eef0f2;color:#18202d;font:16px/1.5 system-ui,sans-serif}button,input,select,textarea{font:inherit}button,a,input,select,textarea{min-height:44px}button{cursor:pointer;border:1px solid #ccd2da;border-radius:10px;padding:10px 16px;background:white;color:inherit}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #9c2d0f;outline-offset:3px}.primary{background:#18202d;color:white;border-color:#18202d}a{color:inherit;text-decoration:none;display:inline-flex;align-items:center;padding:8px}h1,h2,h3,p{margin:0 0 12px}h1{font-size:clamp(24px,4vw,36px);line-height:1.2;letter-spacing:-1px}small,.muted{color:#536073}small{font-size:13px}header,.row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.panel{background:#fff;border:1px solid #d6dce3;border-radius:18px;padding:24px}.pill{display:inline-flex;padding:5px 10px;border-radius:20px;background:#e9eee9;color:#35533c;font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}label{display:block;font-size:14px;font-weight:600;margin-bottom:6px}input,select,textarea{width:100%;border:1px solid #bcc6d1;padding:10px 12px;border-radius:9px;background:#fff;color:#18202d;margin-bottom:16px}input:focus{border-color:#9c2d0f}form{max-width:460px}output{display:block;color:#35533c;margin-top:12px}.art{border-radius:14px;background:linear-gradient(135deg,#c9dce2,#dae3dc);padding:30px;position:relative;overflow:hidden}.art:before{content:\"\";display:block;width:110px;height:110px;border:20px solid #fff8;border-radius:50%;margin:0 auto;animation:rotate 12s linear infinite}.art:after{content:\"\";position:absolute;inset:20% 35%;border:12px solid #18202d22;border-radius:12px;transform:rotate(35deg)}@keyframes rotate{to{transform:rotate(360deg)}}@media(max-width:600px){body{padding:16px}.grid{grid-template-columns:1fr}.panel{padding:18px}}@media(prefers-reduced-motion:reduce){*,*:before{animation:none!important;transition:none!important}}</style></head><body><section class=\"panel\"><header><div><small>Your studio at a glance</small><h1>Project pulse.</h1></div><span class=\"pill\">Sample workspace</span></header><div class=\"grid\" style=\"margin:22px 0\"><div class=\"panel\"><small>Active projects</small><h2>3</h2><small>One clear view of your work.</small></div><div class=\"panel\"><small>Tasks this week</small><h2>24</h2><small>Steady progress, visible outcomes.</small></div></div><label for=\"status\">Filter projects</label><select id=\"status\"><option value=\"all\">All projects</option><option value=\"Active\">Active</option><option value=\"Review\">Review</option></select><button id=\"sort\" aria-pressed=\"false\">Sort by task count</button><div style=\"overflow:auto;margin-top:16px\"><table style=\"width:100%;border-collapse:collapse;text-align:left\"><caption style=\"text-align:left;padding-bottom:12px\">Project activity</caption><thead><tr><th scope=\"col\">Project</th><th scope=\"col\">Status</th><th scope=\"col\">Tasks</th></tr></thead><tbody id=\"rows\"></tbody></table></div><output id=\"count\" aria-live=\"polite\"></output></section><script>const projects=[{name:'Studio website',status:'Active',tasks:8},{name:'Community app',status:'Review',tasks:5},{name:'Research portal',status:'Active',tasks:11}];let sorted=false;function render(){const status=document.querySelector('#status').value,items=projects.filter(p=>status==='all'||p.status===status);if(sorted)items.sort((a,b)=>b.tasks-a.tasks);const rows=document.querySelector('#rows');rows.replaceChildren();items.forEach(p=>{const tr=document.createElement('tr');[p.name,p.status,p.tasks].forEach(value=>{const td=document.createElement('td');td.textContent=String(value);td.style.padding='14px 8px';td.style.borderTop='1px solid #d6dce3';tr.append(td)});rows.append(tr)});document.querySelector('#count').textContent=items.length+' projects shown.'}document.querySelector('#status').addEventListener('change',render);document.querySelector('#sort').addEventListener('click',e=>{sorted=!sorted;e.currentTarget.setAttribute('aria-pressed',String(sorted));render()});render();</script></body></html>","README.md":"# Project pulse dashboard\n\nVersion: 1.0.0\nOriginal getLancer curated recipe. Licence: MIT.\n\n## Setup\nOpen index.html in a modern browser. No packages, installation, API keys or external assets are required. Optional local server: python3 -m http.server 8000.\n\n## Try\nFilter to Active and sort projects by their task count.\n\n## Files\nindex.html contains the working HTML, CSS and JavaScript. LICENSE contains redistribution terms. README.md contains this setup guide.\n\n## Accessibility\nKeyboard controls, visible focus, 44px targets and reduced-motion support. Test your own modifications before release.\n\n## Dependencies\nNone. HTML/CSS and browser JavaScript only. No external fonts or images.\n\n## Data and limits\nSynthetic data held in preview memory. No account service, production credentials, tracking or network requests.\n","LICENSE":"MIT License\n\nCopyright (c) 2026 getLancer contributors\n\nPermission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the \"Software\"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all copies or substantial 