UPDATE component_entries c SET submitted_source=coalesce(c.published_source,r.source)
FROM recipes r WHERE c.recipe_slug=r.source->>'slug' AND c.submitted_source IS NULL AND c.status IN ('PENDING','SUSPENDED');
UPDATE component_entries SET submitted_context=CASE
  WHEN status='SUSPENDED' AND published_context IS NOT NULL THEN published_context
  ELSE jsonb_build_object('title',title,'summary',summary,'contribution',contribution) END
WHERE status IN ('PENDING','SUSPENDED');
ALTER TABLE component_entries ENABLE TRIGGER component_submission_immutable;
INSERT INTO component_releases(component_id,revision,source,context,source_sha256,published_at)
SELECT id,1,published_source,published_context,published_source->>'sha256',published_at
FROM component_entries c WHERE published_source IS NOT NULL AND published_at IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM component_releases r WHERE r.component_id=c.id);
-- Keep the first publication and all releases immutable. New source lives in a private draft.
CREATE OR REPLACE FUNCTION freeze_submitted_component() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.status='PENDING' AND
    ROW(NEW.recipe_slug,NEW.title,NEW.summary,NEW.contribution,NEW.draft_source,NEW.submitted_source,NEW.submitted_context)
    IS DISTINCT FROM ROW(OLD.recipe_slug,OLD.title,OLD.summary,OLD.contribution,OLD.draft_source,OLD.submitted_source,OLD.submitted_context)
  THEN RAISE EXCEPTION 'Submitted component content is immutable'; END IF;
  RETURN NEW;
END $$;
CREATE TABLE component_previews (
  deployment_id uuid PRIMARY KEY,
  component_id uuid NOT NULL,
  revision bigint NOT NULL,
  state varchar(10) NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','READY','REVOKED')),
  expires_at timestamptz NOT NULL,
  archive_sha256 varchar(64) NOT NULL CHECK(archive_sha256 ~ '^[a-f0-9]{64}$'),
  manifest_sha256 varchar(64) NOT NULL CHECK(manifest_sha256 ~ '^[a-f0-9]{64}$'),
  FOREIGN KEY(component_id,revision) REFERENCES component_releases(component_id,revision),
  UNIQUE(component_id,revision)
);
ALTER TABLE component_previews ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON component_previews FROM PUBLIC;
DO $$ BEGIN
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON component_previews FROM anon; END IF;
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON component_previews FROM authenticated; END IF;
END $$;

CREATE FUNCTION freeze_component_preview() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Component preview identities are retained'; END IF;
  IF OLD.state='REVOKED' AND NEW.state<>'REVOKED' THEN RAISE EXCEPTION 'Withdrawn component previews cannot revive'; END IF;
  IF ROW(NEW.deployment_id,NEW.component_id,NEW.revision,NEW.expires_at,NEW.archive_sha256,NEW.manifest_sha256)
    IS DISTINCT FROM ROW(OLD.deployment_id,OLD.component_id,OLD.revision,OLD.expires_at,OLD.archive_sha256,OLD.manifest_sha256)
    THEN RAISE EXCEPTION 'Component preview identity, source hashes and expiry are immutable'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER component_preview_immutable BEFORE UPDATE OR DELETE ON component_previews FOR EACH ROW EXECUTE FUNCTION freeze_component_preview();

-- Keep legacy history intact while preventing any new duplicate source version.
CREATE FUNCTION unique_component_release_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  -- Serialize direct runtime inserts as well as service-mediated publication.
  PERFORM id FROM component_entries WHERE id=NEW.component_id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM component_releases WHERE component_id=NEW.component_id AND source->>'version'=NEW.source->>'version')
    THEN RAISE EXCEPTION 'Reviewed component versions are unique; reuse an unchanged release'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER component_release_version_unique BEFORE INSERT ON component_releases FOR EACH ROW EXECUTE FUNCTION unique_component_release_version();
